EXC_DMSNEG2 = {'type': 'RuntimeError', 'msg': 'zeros: Dimension size must be non-negative.'}
EXC_MSNEG1 = {'type': 'RuntimeError', 'msg': 'upper bound and lower bound inconsistent with step sign'}

# ---- helpers ------------------------------------------------------------------
def _eq(a, b, tag):
    assert a == b, "%s: %r != %r" % (tag, a, b)


def _bits(x):
    return (repr(x), math.copysign(1.0, x))


def _deep(a, b, tag):
    if isinstance(a, dict) and isinstance(b, dict):
        _eq(sorted(a.keys()), sorted(b.keys()), tag + ".keys")
        for k in a:
            _deep(a[k], b[k], tag + "." + str(k))
    elif isinstance(a, list) and isinstance(b, list):
        _eq(len(a), len(b), tag + ".len")
        for i, (x, y) in enumerate(zip(a, b)):
            _deep(x, y, "%s[%d]" % (tag, i))
    elif isinstance(a, float) and isinstance(b, float):
        _eq(_bits(a), _bits(b), tag + ".bits")
    else:
        _eq(a, b, tag)


def C(solve, mode, **kw):
    return solve(mode, **kw)


def _exc(fn):
    try:
        fn()
        return None
    except Exception as e:
        return {"type": type(e).__name__, "msg": str(e)}


def _flat(x):
    if isinstance(x, list):
        out = []
        for v in x:
            out.extend(_flat(v))
        return out
    return [x]


SAFE_N = (1, 2, 3, 4, 5, 6, 8, 9, 10, 11, 12, 16, 20, 24, 32)
RANGES = ("NEG", "UNIT", "FLAT", "FRAC", "NEGDECAY")
PHASES = ("PH0", "PHPI2", "PHPI", "PHNEG", "PHNEG3PI2", "PH2PI", "PHFRAC")

# ---- census / dispatch ---------------------------------------------------------
def check_census_source(solve):
    c = C(solve, "census")
    _eq(c["source"], "pytorch/audio main::src/torchaudio/functional/filtering.py", "src")
    _eq(c["source_lines"], 1702, "lines")
    _eq(c["n_top_level"], 30, "n_top_level")
    _deep(c["funcs"], FUNCS872, "funcs")


def check_census_modes(solve):
    c = C(solve, "census")
    _deep(c["modes"], MODES872, "modes")
    _deep(c["params"], PARAMS872, "params")
    _deep(c["defaults"], DEFAULTS872, "defaults")
    _deep(c["arg_names"],
          ["waveform", "sample_rate", "gain_in", "gain_out", "delay_ms",
           "decay", "mod_speed", "sinusoidal"], "arg_names")
    _deep(c["wave_types"], WAVE_TYPES872, "wave_types")
    _deep(c["data_types"], DATA_TYPES872, "data_types")


def check_census_fresh_dict(solve):
    a = C(solve, "census")
    a["modes"].append("POLLUTED")
    a["defaults"]["gain_in"] = 999.0
    b = C(solve, "census")
    _deep(b["modes"], MODES872, "fresh modes")
    _deep(b["defaults"], DEFAULTS872, "fresh defaults")


def check_mode_dispatch(solve):
    for m in MODES872:
        r = C(solve, m)
        assert isinstance(r, dict), m
    _eq(len(MODES872), 8, "mode count")


def check_unknown_mode(solve):
    _deep(_exc(lambda: C(solve, "no_such_mode")), EXC_UNKNOWN, "unknown mode")


def check_census_full(solve):
    _deep(C(solve, "census"), CENSUS872, "census")


# ---- wave tables ---------------------------------------------------------------
def check_wt_sine_int_grid(solve):
    for n in SAFE_N:
        got = C(solve, "wave_table", wave_type="SINE", data_type="INT",
                table_size=n, min=1.0, max=5.0, wt_phase=math.pi / 2)
        _deep(got, globals()["WT_SINE_INT_N%d" % n], "sine int n=%d" % n)


def check_wt_sine_float_grid(solve):
    for n in SAFE_N:
        got = C(solve, "wave_table", wave_type="SINE", data_type="FLOAT",
                table_size=n, min=1.0, max=5.0, wt_phase=math.pi / 2)
        _deep(got, globals()["WT_SINE_FLOAT_N%d" % n], "sine float n=%d" % n)


def check_wt_sine_byte_grid(solve):
    for n in SAFE_N:
        got = C(solve, "wave_table", wave_type="SINE", data_type="BYTE",
                table_size=n, min=1.0, max=5.0, wt_phase=math.pi / 2)
        _deep(got, globals()["WT_SINE_BYTE_N%d" % n], "sine byte n=%d" % n)


def check_wt_tri_int_grid(solve):
    for n in SAFE_N:
        got = C(solve, "wave_table", wave_type="TRIANGLE", data_type="INT",
                table_size=n, min=1.0, max=5.0, wt_phase=math.pi / 2)
