def check_gain_out_linear(solve):
    a = C(solve, "phaser", gain_out=0.37)["out"]
    b = C(solve, "phaser", gain_out=0.74)["out"]
    for ra, rb in zip(a, b):
        for x, y in zip(ra, rb):
            assert abs(y - 2 * x) < 1e-15, "gain_out linear"


