def check_output_shape_preserved(solve):
    for tag in ("W0", "W1", "W2", "W3", "W4", "W5", "W6", "W7"):
        w = WAVES872[tag]
        shape = []
        cur = w
        while isinstance(cur, list):
            shape.append(len(cur))
            cur = cur[0] if cur else None
        _deep(C(solve, "phaser", waveform=w)["shape"], shape, "shape " + tag)
